const songs=new Map();
const names={qq:'QQ音乐',kugou:'酷狗',kuwo:'酷我',migu:'咪咕',netease:'网易云',local:'本地音源'};
export const localExtensions=new Set(['.mp3','.wav','.flac','.m4a','.aac','.ogg','.opus','.aiff','.aif','.wma','.mp4','.webm']);
export async function importLocalSong(value){const input=value.path||value.url;if(typeof input!=='string')throw Error('需要本地文件路径');const path=await realpath(input.startsWith('file:')?fileURLToPath(input):input);if(!localExtensions.has(extname(path).toLowerCase()))throw Error('请选择音频文件或MP4/WebM音轨');if(!(await stat(path)).isFile())throw Error('本地音源不是文件');const id=createHash('sha256').update(path).digest('hex'),song={source:'local',id,key:'local:'+id,name:value.name||basename(path,extname(path)),artists:value.artists||'',localPath:path,raw:{}};rememberSong(song);return songRecord(song);}
async function json(url,options={},signal){const r=await fetch(url,{...options,signal:signal?AbortSignal.any([signal,AbortSignal.timeout(15000)]):AbortSignal.timeout(15000)});if(!r.ok)throw Error('HTTP '+r.status);return r.json();}
function normalize(source,id,name,artists,raw,extra={}){const s={source,id:String(id),key:source+':'+id,name,artists,raw,...extra};songs.set(s.key,s);return {...s,raw:undefined};}
export function sources(){return Object.entries(names).map(([id,name])=>({id,name,search:id==='local'?'可导入本地路径或选择文件；source=local搜索已导入歌曲':'已实现公开检索；接口可用性以本次请求为准',playback:id==='local'?'直接播放本机文件，支持队列、歌单与进度拖动':'按来源实际返回的音源判断，不能用搜索成功代替可播放'}));}
export async function searchOne(source,keyword,page=1,signal){
 const q=encodeURIComponent(keyword);
 if(source==='qq'){const d=await json('https://u.y.qq.com/cgi-bin/musicu.fcg',{method:'POST',headers:{'Content-Type':'application/json',Referer:'https://y.qq.com/'},body:JSON.stringify({comm:{ct:'19',cv:'1859',uin:'0'},req:{method:'DoSearchForQQMusicDesktop',module:'music.search.SearchCgiService',param:{grp:1,num_per_page:20,page_num:page,query:keyword,search_type:0}}})},signal);const rows=d.req?.data?.body?.song?.list;if(!Array.isArray(rows))throw Error(d.req?.message||'QQ检索未返回歌曲列表');return rows.map(s=>normalize(source,s.mid,s.name,s.singer?.map(x=>x.name).join(' / '),s,{duration:s.interval*1000}));}
 if(source==='kugou'){const d=await json('https://songsearch.kugou.com/song_search_v2?keyword='+q+'&page='+page,{},signal);if(!Array.isArray(d.data?.lists))throw Error(d.error_msg||'酷狗检索未返回列表');return d.data.lists.map(s=>normalize(source,s.FileHash||s.Hash,s.SongName||s.FileName,s.SingerName,s,{duration:Number(s.Duration)*1000}));}
 if(source==='kuwo'){const d=await json('https://www.kuwo.cn/search/searchMusicBykeyWord?vipver=1&client=kt&ft=music&cluster=0&strategy=2012&encoding=utf8&rformat=json&mobi=1&pn='+(page-1)+'&rn=20&all='+q,{headers:{Referer:'https://www.kuwo.cn/'}},signal);if(!Array.isArray(d.abslist))throw Error('酷我检索未返回列表');return d.abslist.map(s=>normalize(source,String(s.MUSICRID).replace('MUSIC_',''),s.SONGNAME,s.ARTIST,s,{duration:Number(s.DURATION)*1000}));}
 if(source==='migu'){const d=await json('https://app.u.nf.migu.cn/pc/resource/song/item/search/v1.0?text='+q+'&pageNo='+page+'&pageSize=20',{},signal);if(!Array.isArray(d))throw Error('咪咕检索未返回列表');return d.map(s=>normalize(source,s.copyrightId,s.songName,s.singerList?.map(x=>x.name).join(' / ')||s.singer,s));}
 if(source==='netease'){const d=await json('https://music.163.com/api/search/get/web',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded',Referer:'https://music.163.com/'},body:new URLSearchParams({s:keyword,type:'1',offset:String((page-1)*30),limit:'30'})},signal);if(!Array.isArray(d.result?.songs))throw Error(d.message||'网易云检索未返回列表');return d.result.songs.map(s=>normalize(source,s.id,s.name,s.artists?.map(a=>a.name).join(' / '),s,{duration:s.duration}));}
 throw Error('未知音源：'+source);
}
export async function search(keyword,source='all',page=1,signal){if(!keyword?.trim()||!Number.isInteger(page)||page<1)throw Error('需要查询词和有效页码');const chosen=source==='all'?Object.keys(names).filter(id=>id!=='local'):[source];const result=await Promise.all(chosen.map(async id=>{try{return {source:id,songs:id==='local'?[...songs.values()].filter(s=>s.source==='local'&&(s.name+' '+s.artists).toLowerCase().includes(keyword.toLowerCase())).slice((page-1)*30,page*30).map(songRecord):await searchOne(id,keyword,page,signal)};}catch(e){if(signal?.aborted)throw e;return {source:id,error:e.message,songs:[]};}}));return {keyword,page,sources:result,note:'这些是候选，尚未证明可播放或已经听过。'};}
export function cachedSong(key){const s=songs.get(key);if(!s)throw Error('先搜索取得该来源的歌曲标识；不同来源的ID不可混用。');return s;}
export function rememberSong(song){if(!names[song.source]||song.key!==song.source+':'+song.id)throw Error('无效歌曲');songs.set(song.key,{...song,raw:song.raw||{contentId:song.contentId}});return song;}
export function songRecord(song){return {key:song.key,source:song.source,id:song.id,name:song.name,artists:song.artists,duration:song.duration,contentId:song.raw?.contentId||song.contentId,...(song.source==='local'?{localPath:song.localPath}:{})};}
export function importSong(value){const source=value.source||'netease',id=String(value.id||'');if(!names[source]||!id||!value.name?.trim())throw Error('需要实际来源、歌曲ID和名称');let providedURL;if(value.url){const u=new URL(value.url),allowed=['music.126.net','music.163.com','qq.com','kugou.com','kuwo.cn','migu.cn'];if(!['https:','http:'].includes(u.protocol)||u.username||u.password||!allowed.some(x=>u.hostname===x||u.hostname.endsWith('.'+x)))throw Error('仅接受实际官方音乐音源域名的HTTP(S)链接');providedURL=u.href;}const s={source,id,key:source+':'+id,name:value.name,artists:value.artists||'',duration:value.duration,providedURL,raw:{}};rememberSong(s);return songRecord(s);}
export async function resolveSong(key,signal){
 const s=cachedSong(key);let url;
 if(s.source==='local'){if(!(await stat(s.localPath)).isFile())throw Error('本地音源不存在');return {...s,raw:undefined};}
 if(s.providedURL)return {...s,raw:undefined,url:s.providedURL,providedURL:undefined};
 if(s.source==='netease'){const d=await json('https://music.163.com/api/song/enhance/player/url?ids='+encodeURIComponent(JSON.stringify([Number(s.id)]))+'&br=128000',{headers:{Referer:'https://music.163.com/'}},signal);url=d.data?.[0]?.url;}
 if(s.source==='qq'){const d=await json('https://u.y.qq.com/cgi-bin/musicu.fcg',{method:'POST',headers:{'Content-Type':'application/json',Referer:'https://y.qq.com/'},body:JSON.stringify({req_1:{module:'vkey.GetVkeyServer',method:'CgiGetVkey',param:{guid:'10000',songmid:[s.id],songtype:[0],uin:'0',loginflag:1,platform:'20'}},loginUin:'0',comm:{uin:'0',format:'json',ct:24,cv:0}})},signal);const x=d.req_1?.data;if(x?.midurlinfo?.[0]?.purl)url=x.sip[0]+x.midurlinfo[0].purl;}
 if(s.source==='kugou'){const d=await json('https://m.kugou.com/app/i/getSongInfo.php?cmd=playInfo&hash='+encodeURIComponent(s.id),{},signal);url=d.url;}
 if(s.source==='kuwo'){const d=await json('https://www.kuwo.cn/api/v1/www/music/playUrl?mid='+encodeURIComponent(s.id)+'&type=music&httpsStatus=1&plat=web_www',{headers:{Referer:'https://www.kuwo.cn/'}},signal);url=d.data?.url;}
 if(s.source==='migu'){const d=await json('https://app.c.nf.migu.cn/MIGUM3.0/strategy/pc/listen/v1.0?scene=&netType=01&resourceType=2&copyrightId='+encodeURIComponent(s.id)+'&contentId='+encodeURIComponent(s.raw.contentId||'')+'&toneFlag=PQ',{headers:{channel:'0146951'}},signal);url=d.data?.url||d.data?.playUrl;}
 if(!url)throw Error(names[s.source]+'未提供可播放音源，请尝试其他来源或版本。');return {...s,raw:undefined,url};
}
import {createHash} from 'node:crypto';
import {realpath,stat} from 'node:fs/promises';
import {basename,extname} from 'node:path';
import {fileURLToPath} from 'node:url';
